"""Patch the supported Hunter ADF for FS-UAE / 68060 using Python alone."""
import argparse
import base64
import hashlib
import os
from pathlib import Path
import tempfile
import zlib

VERSION = '1.0.1'
OUTPUT_NAME = 'hunter-performance.adf'
DISK_SIZE = 901120
SOURCE_SHA256 = '913d8c7cd8bf9096000b81c02acc8d0d7d49440a2cd486c6e1b8a74d18412f21'
OUTPUT_SHA256 = '25279049d251c6f94fdb0ffa9b1b681b81274dc580bf1ca044578d4c16bbf439'
DELTA_SHA256 = 'd2eec61dafaa9a8bd0287705e0fc7f5efa1696a5d08814a60402a97728af79e1'

def sha256(data):
    return hashlib.sha256(data).hexdigest()


def patch_disk(source):
    if len(source) != DISK_SIZE or sha256(source) != SOURCE_SHA256:
        raise ValueError('Unsupported original ADF: expected SHA-256 ' + SOURCE_SHA256)
    try:
        delta = zlib.decompress(base64.b85decode(DELTA_B85))
    except (ValueError, zlib.error) as error:
        raise ValueError('Embedded patch is corrupt') from error
    if len(delta) != DISK_SIZE or sha256(delta) != DELTA_SHA256:
        raise ValueError('Embedded patch is corrupt')
    result = bytes(a ^ b for a, b in zip(source, delta))
    if result[:1024] != source[:1024] or sha256(result) != OUTPUT_SHA256:
        raise ValueError('Patched ADF verification failed')
    return result


def default_output_path(source_path):
    return Path(source_path).with_name(OUTPUT_NAME)


def write_disk(source_path, output_path, force=False):
    source_path = Path(source_path).expanduser()
    output_path = Path(output_path).expanduser()
    if source_path.resolve() == output_path.resolve():
        raise ValueError('The original ADF must not be overwritten')
    if output_path.exists() and source_path.samefile(output_path):
        raise ValueError('The original ADF must not be overwritten (same file)')
    if output_path.is_symlink():
        raise ValueError('Output must not be a symbolic link: ' + str(output_path))
    if output_path.exists() and not force:
        raise FileExistsError('Output already exists (use --force): ' + str(output_path))
    patched = patch_disk(source_path.read_bytes())
    output_path.parent.mkdir(parents=True, exist_ok=True)
    # Verify the complete temporary file before publishing. Without --force,
    # link also protects a destination created after the existence check.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=output_path.parent, prefix='.hunter-', delete=False) as f:
            temporary = Path(f.name)
            f.write(patched)
            f.flush()
            os.fsync(f.fileno())
        if temporary.read_bytes() != patched:
            raise ValueError('Written ADF verification failed')
        if force:
            os.replace(temporary, output_path)
            temporary = None
        else:
            os.link(temporary, output_path)
    finally:
        if temporary is not None:
            temporary.unlink()
    return sha256(patched)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('original', type=Path, help='Unmodified supported Hunter ADF')
    parser.add_argument('-o', '--output', type=Path, help='Output path (default: hunter-performance.adf in this repository)')
    parser.add_argument('-f', '--force', action='store_true', help='Replace existing output; never overwrite the source')
    parser.add_argument('--version', action='version', version='%(prog)s ' + VERSION)
    args = parser.parse_args(argv)
    output = args.output if args.output is not None else Path(__file__).resolve().parent / OUTPUT_NAME
    try:
        digest = write_disk(args.original, output, force=args.force)
    except (OSError, ValueError) as error:
        parser.exit(1, 'Error: %s\n' % error)
    print('Hunter 68060 patch ' + VERSION)
    print('Created %s\nSHA-256: %s' % (output, digest))


